/* =============================================================================
   PANEL-01 · Mi Panel — estilos del dashboard de entrada.
   =============================================================================
   Los colores salen SIEMPRE de `var(--bw-*)`, nunca literales. Dos desviaciones
   del HTML aprobado, ambas contra el design-system §1:

   1 · Las tarjetas del mock son blancas y no hay token de blanco en §1.1: se usa
       `--bw-surface-mist`, el neutro más cercano y el que ya usan las superficies
       claras de la casa.
   2 · El hover del mock lleva una sombra que no tiene token. La "leve elevación"
       de la spec §3 se hace con `translateY(-1px)` en vez de inventar un rgba.
   ========================================================================== */

.body {
  flex: 1;
  overflow-y: auto;
  background: var(--bw-cold-white);
}

.inner {
  padding: 24px 28px 40px;
}

.eyebrow {
  font-family: var(--bw-font-title);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--bw-calibration-blue);
  margin-bottom: 4px;
}

.title {
  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  color: var(--bw-deep-steel);
  margin-bottom: 3px;
}

.sub {
  font-family: var(--bw-font-body);
  font-size: 14px;
  color: var(--bw-steel-mist);
  line-height: 1.6;
  margin-bottom: 24px;
  max-width: 600px;
}

.grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  max-width: 820px;
}

@media (max-width: 720px) {
  .grid {
    grid-template-columns: 1fr;
  }
}

.card {
  appearance: none;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 10px;
  padding: 18px 20px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  gap: 6px;
  text-align: left;
  font-family: var(--bw-font-body);
  color: var(--bw-deep-steel);
  transition: border-color 0.15s ease, transform 0.15s ease;
}

.card:hover:not(:disabled) {
  border-color: var(--bw-line-steel-strong);
  transform: translateY(-1px);
}

.card:focus-visible {
  outline: 2px solid var(--bw-calibration-blue);
  outline-offset: 2px;
}

.disabled {
  cursor: not-allowed;
  opacity: 0.72;
}

.wide {
  grid-column: 1 / -1;
}

.cardHead {
  display: flex;
  align-items: center;
  gap: 9px;
}

.icon {
  width: 32px;
  height: 32px;
  border-radius: 7px;
  background: var(--bw-icon-tint-blue);
  color: var(--bw-calibration-blue);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 17px;
  flex-shrink: 0;
}

.cardTitle {
  font-family: var(--bw-font-title);
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--bw-deep-steel);
}

.num {
  font-family: var(--bw-font-title);
  font-size: 32px;
  font-weight: 700;
  line-height: 1;
  color: var(--bw-deep-steel);
}

.label {
  font-family: var(--bw-font-body);
  font-size: 12px;
  color: var(--bw-steel-mist);
}

.detail {
  font-family: var(--bw-font-body);
  font-size: 13px;
  color: var(--bw-ink-steel);
}

.detail b {
  color: var(--bw-deep-steel);
  font-weight: 600;
}

.metricsRow {
  display: flex;
  gap: 32px;
}

.metric {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

@media (max-width: 520px) {
  .metricsRow {
    flex-direction: column;
    gap: 14px;
  }
}

.loading {
  font-family: var(--bw-font-body);
  font-size: 14px;
  color: var(--bw-steel-mist);
}

.error {
  font-family: var(--bw-font-body);
  font-size: 14px;
  color: var(--bw-error-text);
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: 10px;
  padding: 10px 12px;
}

